{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Alizapride, which shares a pyrrolidine and methoxy-substituted benzamide motif with the query, had an absolute oral bioavailability of 72.5% in subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Encainide, a methoxy-substituted basic amide antiarrhythmic, had an absolute oral bioavailability of 32 ± 7% in normal subjects and higher values in cirrhosis, supporting F ≥ 20% despite basic ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Vernakalant, a dimethoxyphenyl pyrrolidine ether, showed absolute oral bioavailability of 58–71% in healthy volunteers, demonstrating that basic, ionizable amines with similar features can still have high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Letermovir, a highly transferable drug with methoxy and amine-containing features, had an estimated oral bioavailability of about 94% in healthy participants, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Daridorexant, a methoxy-substituted amide/pyrrolidine drug, had an absolute oral bioavailability of 62% in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues, including those with methoxy-substituted aromatics and basic pyrrolidine/piperidine amines similar to the query, show oral bioavailability well above 20%. The physicochemical prior is mixed but low-confidence, and the consistent experimental evidence overrides it.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement exists for the query molecule.",
    "No human permeability or efflux-transporter data are available for the query.",
    "The query's very low logD and full ionization at pH 7.4 are physicochemical concerns, but analogous ionizable basic drugs still achieved high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

